<?php use App\Core\CSRF; ?>
<section class="container py-5" style="max-width:760px"><div class="card"><div class="card-body p-4"><h1 class="h3">Termo de entrega</h1><p><strong><?=htmlspecialchars($delivery['tenant_name'])?></strong><br><?=htmlspecialchars(trim(($delivery['make']??'').' '.$delivery['model'].' '.($delivery['plate']??'')))?></p><div class="border rounded p-3 mb-3" style="white-space:pre-wrap"><?=htmlspecialchars($delivery['terms_snapshot'])?></div><?php if($delivery['accepted_at']):?><div class="alert alert-success">Aceito por <?=htmlspecialchars($delivery['accepted_name'])?> em <?=date('d/m/Y H:i',strtotime($delivery['accepted_at']))?>.</div><?php else:?><form method="post" action="/auto/entrega/<?=htmlspecialchars($token)?>" class="d-grid gap-3"><?=CSRF::field()?><input name="name" class="form-control" placeholder="Nome completo" required><label class="form-check"><input type="checkbox" name="accept" value="1" class="form-check-input" required> <span class="form-check-label">Li e aceito o termo acima.</span></label><button class="btn btn-primary">Confirmar aceite</button></form><?php endif;?></div></div></section>
